from json import dumps


class Tree:
    def __init__(self, label, children=None):
        self.label = label
        self.children = children if children is not None else []

    def __dict__(self):
        return {self.label: [c.__dict__() for c in sorted(self.children)]}

    def __str__(self, indent=None):
        return dumps(self.__dict__(), indent=indent)

    def __lt__(self, other):
        return self.label < other.label

    def __eq__(self, other):
        return self.__dict__() == other.__dict__()

    def from_pov(self, from_node):
        path = self._path_nodes(from_node)
        if path is None:
            raise ValueError("Tree could not be reoriented")
        return self._reorient(path)

    def path_to(self, from_node, to_node):
        if self._path_nodes(to_node) is None:
            raise ValueError("No path found")
        return self.from_pov(from_node)._path_down(to_node)

    def _path_nodes(self, label):
        """Return the list of node references from self down to `label`, or None."""
        if self.label == label:
            return [self]
        for child in self.children:
            rest = child._path_nodes(label)
            if rest is not None:
                return [self] + rest
        return None

    def _path_down(self, label):
        """Return the list of labels from self down to `label`, or None."""
        if self.label == label:
            return [self.label]
        for child in self.children:
            rest = child._path_down(label)
            if rest is not None:
                return [self.label] + rest
        return None

    def _reorient(self, path):
        """Build a new tree rooted at `path[-1]` from the root->target path."""
        target = path[-1]
        chain = None
        for i in range(len(path) - 1):
            node = path[i]
            excluded = path[i + 1]
            children = [c._copy() for c in node.children if c is not excluded]
            if chain is not None:
                children.append(chain)
            chain = Tree(node.label, children)
        new_children = [c._copy() for c in target.children]
        if chain is not None:
            new_children.append(chain)
        return Tree(target.label, new_children)

    def _copy(self):
        return Tree(self.label, [c._copy() for c in self.children])

